object tom {
  var energia = 80
  var posicion = 0

  method velocidad() {
    return 5 + energia/10
  }

  method posicion() {
    return posicion
  }

  method correrA(unRaton) {
    energia -= 0.5 * self.velocidad() * (unRaton.posicion() - self.posicion()).abs()
    posicion = unRaton.posicion()
  }

  method esMasVeloz(unRaton) {
    return self.velocidad() > unRaton.velocidad()
  }
}


object jerry {
  var peso = 3
  var posicion = 10

  method velocidad() {
    return 10 - peso
  }

  method posicion() {
    return posicion
  }
}


object robotRaton {
  const velocidad = 8
  var posicion = 12

  method velocidad() {
    return velocidad
  }

  method posicion() {
    return posicion
  }
}

