test "tom inicialmente es más veloz que jerry" {
	assert.that(tom.esMasVeloz(jerry))
}

test "si tom corre a jerry, luego no es más veloz" {
	tom.correrA(jerry)
	assert.notThat(tom.esMasVeloz(jerry))
}


