object play {
  method jugabilidad() {
    return 10
  }

  method usar() {}
}


object portatil {
  var bateriaBaja = false

  method jugabilidad() {
    if (not bateriaBaja)
      return 8
    else
      return 1
  }

  method usar() {
    bateriaBaja = true
  }
}


object delfina {
  var consolaEnLaMano = play
  var diversion = 0

  method agarrar(consola) {
    consolaEnLaMano = consola
  }

  method jugar(videojuego) {
    diversion += videojuego.diversion(consolaEnLaMano.jugabilidad())
    consolaEnLaMano.usar()
  }

  method diversion() {
    return diversion
  }
}


object arkanoid {
  method diversion(_jugabilidad) {
    return 50
  }
}


object mario {
  method diversion(jugabilidad) {
    if (jugabilidad > 5)
      return 100
    else
      return 15
  }
}


object pokemon {
  method diversion(jugabilidad) {
    return 10 * jugabilidad
  }
}

